    public static function lang(): string
    {
        if (self::$lang !== null) return self::$lang;
        $candidate = strtolower(substr((string)($_GET['lang'] ?? $_COOKIE['odlab_lang'] ?? ''),0,2));
        if (!in_array($candidate,self::SUPPORTED,true)) {
            $candidate = str_starts_with(strtolower((string)($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? 'fr')),'en') ? 'en' : 'fr';
        }
        self::$lang = $candidate;
        if (!headers_sent()) setcookie('odlab_lang',$candidate,['expires'=>time()+31536000,'path'=>'/','samesite'=>'Lax','secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'httponly'=>false]);
        return $candidate;
    }

    public static function t(string $key, array $vars=[]): string
    {
        $lang=self::lang();
        $text=self::STRINGS[$lang][$key] ?? self::STRINGS['fr'][$key] ?? $key;
        foreach($vars as $k=>$v)$text=str_replace('{'.$k.'}',(string)$v,$text);
        return $text;
    }

    public static function js(array $keys): array
    {
        $out=[];foreach($keys as $key)$out[$key]=self::t($key);return$out;
    }

    public static function languageUrl(string $lang): string
    {
        if(!in_array($lang,self::SUPPORTED,true))$lang='fr';
        $q=$_GET;$q['lang']=$lang;
        $path=parse_url((string)($_SERVER['REQUEST_URI']??''),PHP_URL_PATH) ?: '';
        return $path.'?'.http_build_query($q);
    }
}
